vulnerableCode.code:
// VULNERABLE - input is concatenated straight into the SQL string
const sql =
  "SELECT id, username, is_admin FROM users " +
  "WHERE username = '" + username + "' AND password = '" + password + "'";
const row = db.prepare(sql).get(); // code + data in one string => injection

secureCode.code:
// SECURE - values are BOUND as parameters, never parsed as SQL
const row = db
  .prepare("SELECT id, username, is_admin FROM users WHERE username = ? AND password = ?")
  .get(username, password);
// Defense in depth: never store plaintext passwords - hash (bcrypt/argon2), compare in constant time.

secureCodeVariants.code:
// pg — bind username/password as $1/$2; the driver never parses them as SQL
const { rows } = await client.query(
  'SELECT id, username, is_admin FROM users WHERE username = $1 AND password = $2',
  [username, password],
);
const row = rows[0];
// mysql2: conn.execute('... WHERE username = ? AND password = ?', [username, password])

// PDO — prepared statement; values are bound, never concatenated
$stmt = $pdo->prepare(
    'SELECT id, username, is_admin FROM users WHERE username = ? AND password = ?'
);
$stmt->execute([$username, $password]);
$row = $stmt->fetch(PDO::FETCH_ASSOC);

// JDBC — PreparedStatement binds each value with setString
PreparedStatement ps = conn.prepareStatement(
    "SELECT id, username, is_admin FROM users WHERE username = ? AND password = ?");
ps.setString(1, username);
ps.setString(2, password);
ResultSet rs = ps.executeQuery();

// ADO.NET — bind via SqlParameter; input is never parsed as SQL
using var cmd = new SqlCommand(
    "SELECT id, username, is_admin FROM users WHERE username = @u AND password = @p", conn);
cmd.Parameters.Add(new SqlParameter("@u", username));
cmd.Parameters.Add(new SqlParameter("@p", password));
using var reader = cmd.ExecuteReader();
// EF Core: db.Users.FirstOrDefault(x => x.Username == username && x.Password == password)

// database/sql — args bind to placeholders, never string-concatenated
row := db.QueryRow(
    "SELECT id, username, is_admin FROM users WHERE username = $1 AND password = $2",
    username, password,
)
err := row.Scan(&id, &name, &isAdmin)
// MySQL / SQLite drivers use ? placeholders instead of $1/$2.

// Laravel Query Builder — values are bound, sent apart from the SQL
$user = DB::table('users')
    ->where('username', $username)
    ->where('password', $password)
    ->first();
// Raw still binds: ->whereRaw('username = ? AND password = ?', [$username, $password])

// Spring JdbcTemplate — args bind to ? placeholders positionally
List<User> rows = jdbcTemplate.query(
    "SELECT id, username, is_admin FROM users WHERE username = ? AND password = ?",
    userRowMapper, username, password);
// JPA: @Query("... WHERE u.username = :u AND u.password = :p") + @Param bindings
